<template>
  <div class="row full-height min-height-88vh">
    <q-space />
    <div class="flex column border-bdbdbd p-10" v-if="!activeSupplierSidebar">
      <q-icon
        name="forum"
        color="primary"
        @click="activeSupplierSidebar = 'chat'"
        class="cursor-pointer"
      />
      <q-icon
        name="email"
        color="primary"
        @click="activeSupplierSidebar = 'email'"
        class="p-t-5 cursor-pointer"
      />
    </div>
    <div class="flex column border-bdbdbd p-10 col-10" v-else>
      <SupplierDetailsChat v-if="activeSupplierSidebar === 'chat'" />
      <SupplierDetailsEmail v-if="activeSupplierSidebar === 'email'" />
    </div>
  </div>
</template>
<script lang="ts">
import SupplierDetailsChat from 'src/supplier/components/SupplierDetailsChat.vue';
import SupplierDetailsEmail from 'src/supplier/components/SupplierDetailsEmail.vue';
import { defineComponent, ref, watch } from 'vue';
import { storeToRefs } from 'pinia';
import { useWebSocketStore } from 'src/store/websocket.store';
import { useSupplierLayoutsStore } from 'src/store/main';

export default defineComponent({
  components: {
    SupplierDetailsChat,
    SupplierDetailsEmail,
  },
  data() {
    return {
      newChats: 0 as number,
      id: null as any,
    };
  },
  mounted() {
    this.sendSubcription(this.$route.params.id);
    this.CheckSupplierChatOnline(true);
  },
  beforeUnmount() {
    this.reSetChat();
  },
  beforeRouteLeave: function (to: any, from: any, next: any) {
    this.CheckSupplierChatOnline(false);
    next();
  },
  methods: {
    async sendSubcription(org_id: any) {
      await this.connect();
      try {
        if (this.socket.readyState !== WebSocket.OPEN) {
          await this.connect();
        }
        this.subscribeToChat('chat_supplier_detail', org_id);
        this.getChatHistory(org_id, this.chat_limit, this.chat_page);
      } catch (error) {
        logInfo(error, 'error');
      }
    },
  },
  callOnlineInterval(interval: boolean) {
    if (interval) {
      setInterval(() => {
        this.CheckSupplierChatOnline(this.$route.params.id);
      }, 30000);
    }
  },
  setup() {
    const supplier_layouts_store = useSupplierLayoutsStore();
    const { activeSupplierSidebar } = storeToRefs(supplier_layouts_store);
    const { CheckSupplierChatOnline } = supplier_layouts_store;
    const websocket_store = useWebSocketStore();
    const { subscribeToChat, getChatHistory, reSetChat, connect } =
      websocket_store;
    const { socket } = storeToRefs(websocket_store);
    const { chat, chat_limit, chat_page } = storeToRefs(websocket_store);

    return {
      activeSupplierSidebar,
      subscribeToChat,
      getChatHistory,
      CheckSupplierChatOnline,
      chat,
      chat_limit,
      chat_page,
      reSetChat,
      connect,
      socket,
    };
  },
});
</script>
