<template>
  <div
    :style="{ height: chat_hieght }"
    class="q-pa-sm justify-center scroll"
    ref="scrollableDiv"
    @scroll="handleScroll"
  >
    <div class="row justify-center q-my-md" v-if="is_more_chat">
      <q-spinner color="primary" name="dots" size="20px" />
    </div>
    <div
      v-for="(item, index) in internalChat"
      class="chatBox width-100-percent"
      :key="index"
    >
      <q-chat-message
        v-if="shouldDisplayLabel(index)"
        :label="getMessageLabel(item.created_on)"
        class="dateTextLabel"
      />
      <template v-if="item.chat_type === 'INTERNAL'">
        <q-chat-message
          v-if="userLoginId === item.created_by"
          :name="`${item.user?.first_name} ${item.user?.last_name} &nbsp;<div style=\'font-size:10px;\'>${formatDateAccordingToPreference(item.created_on)}</div>`"
          :text="chatMessage(item?.message as string)"
          size="auto"
          name-html
          text-html
          sent
          :text-color="$q.dark.isActive ? 'white' : 'dark'"
        />

        <q-chat-message
          v-else
          :name="`${item.user?.first_name} ${item.user?.last_name} &nbsp;<div style=\'font-size:10px;\'>${formatDateAccordingToPreference(item.created_on)}</div>`"
          :text="chatMessage(item?.message as string)"
          size="auto"
          name-html
          text-html
          :text-color="$q.dark.isActive ? 'white' : 'dark'"
          :bg-color="$q.dark.isActive ? 'grey-7' : 'grey-3'"
        />
      </template>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, watch } from 'vue';
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/Settings/setting.store';
import { getUserDetailFromkey } from 'src/utils/UserDetails';
import { useWebSocketStore } from 'src/store/websocket.store';
import dateUtils from 'src/utils/date';
import { useSupplierLayoutsStore } from 'src/store/main';

export default defineComponent({
  mixins: [dateUtils],
  props: {
    chat_hieght: {
      type: String,
      default: 'calc(100vh - 240px)',
    },
  },
  components: {},
  computed: {
    internalChat(): any[] {
      const chats = this.chat.filter(
        (item: any) => item.chat_type === 'INTERNAL',
      );
      return chats as any[];
    },
  },
  data() {
    return {
      userLoginId: null as any,
      id: null as any,
      scrollableDiv: ref(null) as any,
    };
  },
  watch: {
    '$route.params.id': {
      immediate: true,
      handler(newId, oldId) {
        this.id = newId;
      },
    },
    chat: {
      immediate: true,
      handler(newChat) {
        if (newChat.length > 0) {
          this.updateMessageLabels();
        }
      },
    },
  },

  beforeMount() {
    window.removeEventListener('scroll', this.scrollChatToBottom);
  },
  mounted() {
    const userLogin = getUserDetailFromkey('id');
    if (userLogin) {
      this.userLoginId = userLogin;
    }
    this.scrollChatToBottom();
    window.addEventListener('scroll', this.scrollChatToBottom);
  },
  methods: {
    scrollChatToBottom() {
      const scrollableDiv = this.$refs.scrollableDiv as HTMLElement;
      if (scrollableDiv) {
        requestAnimationFrame(() => {
          scrollableDiv.scrollTop = scrollableDiv.scrollHeight;
        });
      }
    },
    updateMessageLabels() {
      for (let i = 0; i < this.internalChat.length; i++) {
        this.internalChat[i].showLabel = this.shouldDisplayLabel(i);
        this.internalChat[i].label = this.getMessageLabel(
          this.internalChat[i].created_on,
        );
      }
    },
    shouldDisplayLabel(index: number) {
      if (index === 0) return true;
      const prevMessageDate = new Date(
        this.internalChat[index - 1].created_on,
      ).toDateString();
      const currentMessageDate = new Date(
        this.internalChat[index].created_on,
      ).toDateString();
      return prevMessageDate !== currentMessageDate;
    },
    getMessageLabel(date: any) {
      const messageDate = new Date(date);
      const today = new Date();
      const yesterday = new Date(today);
      yesterday.setDate(yesterday.getDate() - 1);

      const messageDateString = messageDate.toDateString();
      const todayDateString = today.toDateString();
      const yesterdayDateString = yesterday.toDateString();

      if (messageDateString === todayDateString) {
        return this.$t('today');
      } else if (messageDateString === yesterdayDateString) {
        return this.$t('yesterday');
      } else {
        return this.formatDateAccordingToPreference(messageDateString);
      }
    },
    handleScroll() {
      const scrollTop = this.$refs.scrollableDiv as HTMLElement;
      if (scrollTop.scrollTop === 0) {
        this.onLoad();
      }
    },
    onLoad() {
      if (this.is_more_chat && this.processIncrease) {
        this.proccessing = true;
        this.chat_page = this.chat_page + 1;
        try {
          setTimeout(() => {
            this.getChatHistory(
              this.$route.params.id,
              this.chat_limit,
              this.chat_page,
            );
            this.scrollChatToBottom();
            window.addEventListener('scroll', this.scrollChatToBottom);
          }, 3000);
        } catch (error) {
          logError(error);
        } finally {
          this.proccessing = false;
        }
      }
    },
    chatMessage(message: string): string[] {
      return [message.replace(/\n/g, '<br>')];
    },
  },
  setup() {
    const supplier_layouts_store = useSupplierLayoutsStore();
    const { activeSupplierSidebar } = storeToRefs(supplier_layouts_store);
    const websocket_store = useWebSocketStore();
    const { sendChat, getChatHistory } = websocket_store;
    const {
      chat,
      chat_limit,
      chat_page,
      is_more_chat,
      proccessing,
      processIncrease,
    } = storeToRefs(websocket_store);

    const { datePattern } = useSettingStore();

    return {
      is_more_chat,
      proccessing,
      activeSupplierSidebar,
      textChat: ref(''),
      chat,
      processIncrease,
      chat_limit,
      chat_page,
      datePattern,
      sendChat,
      getChatHistory,
    };
  },
});
</script>
