<template>
  <div class="row text-primary">
    <div class="cursor-pointer" @click="activeSupplierSidebar = ''">
      <q-icon name="forum" />
      &nbsp;&nbsp;{{ $t('chat') }}
    </div>
  </div>

  <!-- internal chat-->
  <div
    class="full-width position-relative"
    id="chat_panel_customize"
    v-if="!isSupplierUser()"
  >
    <q-tabs
      v-model="chat_tab"
      dense
      active-class="highlighted-back"
      indicator-color="primary"
      active-color="primary"
      align="justify"
    >
      <q-tab name="INTERNAL" :label="$t('Internal')" />
      <q-tab name="SUPPLIER" :label="$t('supplier')" />
    </q-tabs>
    <q-separator />

    <q-tab-panels v-model="chat_tab" animated>
      <q-tab-panel name="INTERNAL">
        <InternalChats />
      </q-tab-panel>

      <q-tab-panel name="SUPPLIER">
        <SupplierChats />
      </q-tab-panel>
    </q-tab-panels>

    <q-form @submit="submitChat($event, chat_tab)" class="row q-gutter-md items-center">
      <q-input
        type="textarea"
        style="flex-grow: 1"
        v-model="textChat"
        placeholder="Start writing..."
        dense
        outlined
        class="chat_supplier"
        @keydown.enter.exact.prevent="submitChat"
        @keydown.enter.shift.exact.prevent="textChat += '\n'"
      />
      <q-icon
        name="send"
        @click="submitChat"
        :color="textChat.trim() ? 'primary' : 'grey'"
        :class="{
          'pointer-events-none': !textChat.trim(),
          'cursor-pointer': textChat.trim(),
        }"
      />
    </q-form>

    <div class="toogle-chat-icon">
      <q-btn
        dense
        round
        unelevated
        color="primary"
        icon="chevron_right"
        class="drawer-close-button"
        @click="activeSupplierSidebar = ''"
      />
    </div>
  </div>
  <!-- supplier user chat -->
  <div class="full-width position-relative" id="chat_panel_customize" v-else>
    <SupplierChats :chat_hieght="supplierUserChatHeight" />

    <q-form
      @submit="submitChat($event, 'SUPPLIER')"
      class="row q-gutter-md items-center"
    >
      <q-input
        type="textarea"
        style="flex-grow: 1"
        v-model="textChat"
        placeholder="Start writing..."
        dense
        outlined
        class="chat_supplier"
        @keydown.enter.exact.prevent="submitChat($event, 'SUPPLIER')"
        @keydown.enter.shift.exact.prevent="textChat += '\n'"
      />
      <q-icon
        name="send"
        @click="submitChat($event, 'SUPPLIER')"
        :color="textChat.trim() ? 'primary' : 'grey'"
        :class="{
          'pointer-events-none': !textChat.trim(),
          'cursor-pointer': textChat.trim(),
        }"
      />
    </q-form>

    <div class="toogle-chat-icon">
      <q-btn
        dense
        round
        unelevated
        color="primary"
        icon="chevron_right"
        class="drawer-close-button"
        @click="activeSupplierSidebar = ''"
      />
    </div>
  </div>

  <q-inner-loading :showing="proccessing" class="z-index-2">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { defineComponent, ref, watch } from 'vue';
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/Settings/setting.store';
import { getUserDetailFromkey, isSupplierUser } from 'src/utils/UserDetails';
import { useWebSocketStore } from 'src/store/websocket.store';
import dateUtils from 'src/utils/date';
import InternalChats from 'src/supplier/components/dynamic/InternalChat.vue';
import SupplierChats from 'src/supplier/components/dynamic/SupplierChat.vue';
import { useSupplierLayoutsStore } from 'src/store/Settings/supplier_layouts_builder.store';

export default defineComponent({
  mixins: [dateUtils],
  components: {
    InternalChats,
    SupplierChats,
  },
  data() {
    return {
      userLoginId: null as any,
      id: null as any,
      scrollableDiv: ref(null) as any,
      chat_tab: ref('INTERNAL'),
      supplierUserChatHeight: 'calc(100vh - 210px)',
    };
  },
  watch: {
    '$route.params.id': {
      immediate: true,
      handler(newId, oldId) {
        this.id = newId;
      },
    },
    chat: {
      immediate: true,
      handler(newChat) {
        if (newChat.length > 0) {
          this.updateMessageLabels();
        }
      },
    },
  },

  beforeMount() {
    window.removeEventListener('scroll', this.scrollChatToBottom);
  },
  mounted() {
    const userLogin = getUserDetailFromkey('id');
    if (userLogin) {
      this.userLoginId = userLogin;
    }
    this.scrollChatToBottom();
    window.addEventListener('scroll', this.scrollChatToBottom);
  },
  methods: {
    scrollChatToBottom() {
      const scrollableDiv = this.$refs.scrollableDiv as HTMLElement;
      if (scrollableDiv) {
        requestAnimationFrame(() => {
          scrollableDiv.scrollTop = scrollableDiv.scrollHeight;
        });
      }
    },
    updateMessageLabels() {
      for (let i = 0; i < this.chat.length; i++) {
        this.chat[i].showLabel = this.shouldDisplayLabel(i);
        this.chat[i].label = this.getMessageLabel(this.chat[i].created_on);
      }
    },
    shouldDisplayLabel(index: number) {
      if (index === 0) return true;
      const prevMessageDate = new Date(
        this.chat[index - 1].created_on,
      ).toDateString();
      const currentMessageDate = new Date(
        this.chat[index].created_on,
      ).toDateString();
      return prevMessageDate !== currentMessageDate;
    },
    getMessageLabel(date: any) {
      const messageDate = new Date(date);
      const today = new Date();
      const yesterday = new Date(today);
      yesterday.setDate(yesterday.getDate() - 1);

      const messageDateString = messageDate.toDateString();
      const todayDateString = today.toDateString();
      const yesterdayDateString = yesterday.toDateString();

      if (messageDateString === todayDateString) {
        return this.$t('today');
      } else if (messageDateString === yesterdayDateString) {
        return this.$t('yesterday');
      } else {
        return this.formatDateAccordingToPreference(messageDateString);
      }
    },
    handleScroll() {
      const scrollTop = this.$refs.scrollableDiv as HTMLElement;
      if (scrollTop.scrollTop === 0) {
        this.onLoad();
      }
    },
    onLoad() {
      if (this.is_more_chat && this.processIncrease) {
        this.proccessing = true;
        this.chat_page = this.chat_page + 1;
        try {
          setTimeout(() => {
            this.getChatHistory(
              this.$route.params.id,
              this.chat_limit,
              this.chat_page,
            );
            this.scrollChatToBottom();
            window.addEventListener('scroll', this.scrollChatToBottom);
          }, 3000);
        } catch (error) {
          logError(error);
        }
      }
    },
    submitChat(e: any, chat_type: string) {
      e.preventDefault();
      this.proccessing = true;
      if (!this.textChat.trim() || this.textChat.trim() === '') {
        return;
      } else {
        const data = {
          type: 'chat_supplier_detail',
          data: {
            message: this.textChat.trim(),
            supplier_as_org_id: this.$route.params.id,
            chat_type: chat_type ?? this.chat_tab,
          },
        };
        try {
          this.sendChat(data);
          this.textChat = '';
        } catch (error) {
          logInfo(error, 'error');
        }
      }
    },
    chatMessage(message: string): string[] {
      return [message.replace(/\n/g, '<br>')];
    },
  },
  setup() {
    const supplier_layouts_store = useSupplierLayoutsStore();
    const { activeSupplierSidebar } = storeToRefs(supplier_layouts_store);
    const websocket_store = useWebSocketStore();
    const { sendChat, getChatHistory } = websocket_store;
    const {
      chat,
      chat_limit,
      chat_page,
      is_more_chat,
      proccessing,
      processIncrease,
    } = storeToRefs(websocket_store);

    const { datePattern } = useSettingStore();

    return {
      is_more_chat,
      proccessing,
      activeSupplierSidebar,
      textChat: ref(''),
      chat,
      processIncrease,
      chat_limit,
      chat_page,
      datePattern,
      sendChat,
      getChatHistory,
      isSupplierUser,
    };
  },
});
</script>
