<template>
  <div class="row text-primary" style="text-transform: uppercase">
    <div class="cursor-pointer" @click="activeSupplierSidebar = ''">
      <q-icon name="email" />
      &nbsp;&nbsp;{{ $t('mail') }}
    </div>
  </div>

  <!-- <div style="height: calc(100vh - 170px);"> -->
  <div style="position: relative">
    <q-form class="flex column" style="font-size: 13px">
      <q-input v-model="supplierEmail.to" name="to" :label="$t('to')">
        <template v-slot:label>
          <q-label> {{ $t('to') }}: <span style="color: red">*</span> </q-label>
        </template>
      </q-input>
      <span v-if="emailToError" name="error" style="color: red">
        {{ emailToError }}
      </span>

      <q-input v-model="supplierEmail.cc" name="cc" :label="`${$t('cc')}:`" />
      <span v-if="emailCCError" name="error" style="color: red">
        {{ emailCCError }}
      </span>

      <q-input
        v-model="supplierEmail.subject"
        name="subject"
        :label="$t('subject')"
      >
        <template v-slot:label>
          <q-label>
            {{ $t('subject') }}: <span style="color: red">*</span>
          </q-label>
        </template>
      </q-input>
      <span v-if="subjectError" name="error" style="color: red">
        {{ subjectError }}
      </span>

      <q-file
        v-model="supplierEmail.file"
        :label="`${$t('file')}:`"
        multiple
        append
        use-chips
      >
        <template v-slot:append>
          <q-icon name="attach_file" />
        </template>
      </q-file>

      <q-input
        v-model="supplierEmail.message"
        name="message"
        :label="`${$t('message')}:`"
        type="textarea"
      />
    </q-form>
    <div class="row" style="text-align: right; padding-top: 5px">
      <q-space />
      <q-icon
        class="cursor-pointer"
        name="send"
        color="primary"
        @click="handleSendEmail"
      />
    </div>

    <!-- </div> -->

    <div style="position: absolute; top: 50%; left: -27px">
      <q-btn
        dense
        round
        unelevated
        color="primary"
        icon="chevron_right"
        class="drawer-close-button"
        @click="activeSupplierSidebar = ''"
      />
    </div>
  </div>
  <q-inner-loading :showing="loading">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { ref } from 'vue';
import { defineComponent } from 'vue';
import { supplierDataApiService } from '../service';
import { ApiExceptions } from 'src/exceptions';
import { useSupplierLayoutsStore } from 'src/store/main';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
    data() {
    let loading = false;
    return {
      loading,
      emailToError: '',
      emailCCError: '',
      subjectError: '',
    };
  },
  setup() {
    const supplier_layouts_store = useSupplierLayoutsStore();
    const { activeSupplierSidebar } = storeToRefs(supplier_layouts_store);
    const supplierEmail = ref({
      to: '',
      cc: '',
      subject: '',
      file: [] as File[],
      message: '',
    });

    return {
      activeSupplierSidebar,
      supplierEmail,
    };
  },
  methods: {
    isValidEmail(email: string) {
      const re = /\S+@\S+\.\S+/;
      return re.test(email);
    },
    validationSendEmail() {
      let error = false;

      if (this.supplierEmail.to === '') {
        this.emailToError = 'Email is required';
        error = true;
      } else if (
        this.supplierEmail.to &&
        !this.isValidEmail(this.supplierEmail.to)
      ) {
        this.emailToError = 'Email is invalid';
        error = true;
      } else {
        this.emailToError = '';
      }

      if (this.supplierEmail.cc && !this.isValidEmail(this.supplierEmail.cc)) {
        ((this.emailCCError = 'Email is invalid'), (error = true));
      } else {
        this.emailCCError = '';
      }

      if (this.supplierEmail.subject === '' || !this.supplierEmail.subject) {
        this.subjectError = 'Subject is required';
        error = true;
      } else {
        this.subjectError = '';
      }

      return error;
    },
    async handleSendEmail() {
      try {
        let hasError = this.validationSendEmail();
        if (!hasError) {
          this.loading = true;
          const formData = new FormData();
          formData.append('recipients', this.supplierEmail.to);
          formData.append('cc', this.supplierEmail.cc);
          formData.append('subject', this.supplierEmail.subject);
          formData.append('description', this.supplierEmail.message);
          if (this.supplierEmail.file) {
            this.supplierEmail.file.forEach((file) => {
              formData.append('files', file);
            });
          }

          const response =
            await supplierDataApiService.supplierSendEmail(formData);
          if (response) {
            notify.success(this.$t('email_send_success'));
            Object.assign(this.supplierEmail, {
              to: '',
              cc: '',
              subject: '',
              file: [],
              message: '',
            });
          }
        }
      } catch (e: any) {
        const msg = ApiExceptions.getErrorMessage(e);
        notify.error(msg);
      } finally {
        this.loading = false;
      }
    },
  },
});
</script>

<style scoped lang="scss">
:deep(.q-textarea.q-field--labeled .q-field__native) {
  height: calc(100vh - 420px);
}
:deep(.q-chip) {
  min-width: 50px !important;
  max-width: 220px !important;
}
