<template>
  <q-stepper
    v-model="step"
    alternative-labels
    color="primary"
    class="bg-transparent"
    flat
    animated
    header-nav
  >
    <template v-for="(metaStep, index) in formLayout" :key="metaStep.name">
      <q-step
        v-if="!metaStep.hidden"
        :name="Number(index) + 1"
        :title="$t(metaStep.title)"
        :icon="metaStep.icon === 'edi' ? iconUrl : metaStep.icon"
        :active-icon="metaStep.icon === 'edi' ? iconUrl : metaStep.icon"
        :done-icon="metaStep.icon === 'edi' ? iconUrl : metaStep.icon"
        :done="step > Number(index) + 1"
      />
    </template>
  </q-stepper>
</template>
<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useSupplierLayoutsStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

export default defineComponent({
  el: '#app',
  components: {},
  watch: {},
  computed: {
    iconUrl: function () {
      let url = '';
      if (this.$q.dark.isActive) {
        url = 'img:/supplier/supplier_edi_dark_mode.svg';
      } else {
        url = 'img:/supplier/supplier_edi.svg';
      }
      return url;
    },
  },
  data() {
    return {
      //
    };
  },
  setup() {
    const supplier_layouts_store = useSupplierLayoutsStore();
    const { formLayout, step } = storeToRefs(supplier_layouts_store);
    return {
      formLayout,
      step,
    };
  },
  methods: {},
});
</script>
