<template>
  <QForm ref="currentForm" class="row" v-if="renderComponent">
    <template v-if="step.after">
      <template v-for="(meta_field, index) in step.rows" :key="index">
        <template v-if="currentField && currentField[index]">
          <template
            v-for="(field, fieldIndex) in meta_field"
            :key="index + field.name + fieldIndex"
          >
            <Field
              v-show="!field.is_hidden"
              :meta_field="field"
              :afterClick="() => onClickActionButton(Number(index), step.name)"
              :innerHtml="actionIcon(Number(index))"
              :btnVisible="Number(index) > 0"
              :readonly="field.readonly"
              @update:model-value="
                handleModelValueUpdate(step.name, field, $event, Number(index))
              "
              v-model="currentField[index][field.field_name]"
              :enableMetadata="true"
            />
          </template>
        </template>
      </template>
    </template>
    <template v-else v-for="(meta_field, index) in step.rows" :key="index">
      <Field
        v-show="!meta_field.is_hidden"
        :meta_field="meta_field"
        :readonly="meta_field.readonly"
        @update:model-value="
          handleModelValueUpdate(step.name, meta_field, $event)
        "
        v-model="currentField[meta_field.field_name]"
        :enableMetadata="true"
      />
    </template>
  </QForm>
  <ConfirmDialog
    v-model="confirm_payment_term_field"
    :message="$t('payment_term_hint')"
    :confirm-label="$t('confirm')"
    :btnCancel="false"
  />
</template>

<script lang="ts">
import { defineComponent, ref, toRef } from 'vue';
import { useSupplierLayoutsStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import Field from 'src/supplier/components/dynamic/form/Field.vue';
import { QForm } from 'quasar';
import ConfirmDialog from 'src/supplier/pages/ConfirmDialog.vue';
import { supplierDocumentType } from 'src/pages/Settings/SupplierLayouts/formBuilderConstants';

export default defineComponent({
  el: '#app',
  components: {
    Field,
    QForm,
    ConfirmDialog,
  },
  props: {
    step: {
      type: Object,
      required: true,
    },
  },
  computed: {},
  watch: {},
  // mounted: function() {

  // },
  data() {
    return {};
  },
  setup(props) {
    const supplier_layouts_store = useSupplierLayoutsStore();
    const {
      formLayout,
      renderComponent,
      formConfigure,
      supplierForm,
      status,
      layout_type,
    } = storeToRefs(supplier_layouts_store);
    const { onClickActionButton } = supplier_layouts_store;
    const currentField = toRef(formConfigure.value, props.step['name']);
    const currentForm = toRef(supplierForm.value, props.step['name']);

    const actionIcon = (index: number) => (index === 0 ? 'add' : 'remove');
    return {
      formLayout,
      renderComponent,
      formConfigure,
      supplierForm,
      currentForm,
      currentField,
      onClickActionButton,
      actionIcon,
      confirm_payment_term_field: ref(false),
      status,
      layout_type,
    };
  },
  methods: {
    handleModelValueUpdate(
      group_name: any,
      field: any,
      newValue: any,
      index?: number,
    ) {
      if (field.field_name === 'payment_term' && newValue !== 'N90') {
        this.confirm_payment_term_field = true;
      }
    },
  },
});
</script>
