<template>
  <div>
    <q-list bordered class="rounded-borders">
      <template v-for="(metaStep, index) in formLayout" :key="metaStep.name">
        <template v-if="!metaStep.hidden">
          <q-expansion-item
            expand-separator
            :label="$t(metaStep.title)"
            header-class="text-primary"
            :model-value="step === Number(index) + 1"
            @update:model-value="toggle(Number(index))"
          >
            <template v-slot:header>
              <q-item-section avatar>
                <template v-if="metaStep.icon === 'edi'">
                  <EdiIcon class="q-ml-xs" />
                </template>
                <template v-else>
                  <q-icon :name="metaStep.icon" class="q-ml-xs" />
                </template>
              </q-item-section>
              <q-item-section>
                {{ $t(metaStep.title) }}
              </q-item-section>
            </template>
            <q-separator />
            <q-card>
              <q-card-section>
                <SupplierStep :step="metaStep" :key="metaStep.name" />
                <div class="row q-mt-md" style="align-items: center">
                  <q-btn
                    v-if="step !== 1"
                    style="background: #9e9e9e"
                    text-color="white"
                    @click="prev"
                    :label="$t('back')"
                    class="q-ml-sm"
                  />
                  <span v-if="index === 0"
                    >{{ $t('last_modified_at') }}:
                    {{
                      last_updated_at
                        ? formatDateAccordingToPreference(last_updated_at)
                        : '--'
                    }}</span
                  >
                  <q-space />
                  <q-btn
                    v-if="step < formLayout.length"
                    @click="next"
                    color="primary"
                    :label="
                      step === formLayout.length ? $t('finish') : $t('next')
                    "
                  />
                </div>
              </q-card-section>
            </q-card>
          </q-expansion-item>
          <q-separator />
        </template>
      </template>
    </q-list>
  </div>
</template>
<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useSettingStore, useSupplierLayoutsStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { date } from 'quasar';
import SupplierStep from 'src/supplier/components/dynamic/SupplierStep.vue';
import dateUtils from 'src/utils/date';
import EdiIcon from 'src/pages/Settings/SupplierLayouts/component/EdiIcon.vue';

export default defineComponent({
  mixins: [dateUtils],
  el: '#app',
  components: {
    SupplierStep,
    EdiIcon,
  },
  mounted() {
    // this.init();
  },
  data() {
    return {
      //
    };
  },
  setup() {
    const supplier_layouts_store = useSupplierLayoutsStore();
    const { formLayout, step, last_updated_at } = storeToRefs(
      supplier_layouts_store,
    );
    const { prev, next, goto, toggle } = useSupplierLayoutsStore();

    const { datePattern } = useSettingStore();
    return {
      formLayout,
      last_updated_at,
      step,
      prev,
      next,
      goto,
      toggle,
      datePattern,
    };
  },
  methods: {},
});
</script>
